import requestsimport osfrom bs4 import BeautifulSoupfrom dotenv import load_dotenvfrom openai import OpenAI# Headers for requestsheaders = { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/117.0.0.0 Safari/537.36"}def loadAPIKey():    load_dotenv(override=True)    api_key = os.getenv('OPENAI_API_KEY')    if api_key and api_key.startswith('sk-proj-') and len(api_key)>10:        print("API key looks good so far")        return api_key    else:        print("There might be a problem with your API key? Please visit the troubleshooting notebook!")        return None# Initialize OpenAI apiKey = loadAPIKeyopenai = OpenAI(api_key=apiKey)class Website:        def __init__(self, url):        self.url = url        try:            response = requests.get(url, headers=headers, timeout=10)            response.raise_for_status()        except requests.exceptions.RequestException as e:            print(f"Failed to fetch {url}: {e}")            self.body = b""            self.title = f"Failed to load {url}"            self.text = ""            self.links = []            return                self.body = response.content        soup = BeautifulSoup(self.body, 'html.parser')        self.title = soup.title.string if soup.title else "No title found"        if soup.body:            for irrelevant in soup.body(["script", "style", "img", "input"]):                irrelevant.decompose()            self.text = soup.body.get_text(separator="\n", strip=True)        else:            self.text = ""        links = [link.get('href') for link in soup.find_all('a')]        self.links = [link for link in links if link]    def getContents(self):        return f"Webpage Title:\n{self.title}\nWebpage Contents:\n{self.text}\n\n"